UPDATE ticket_source_session_mapping
SET source_status_value=#{sourceStatusValue},
    source_status_text=#{sourceStatusText},
    source_updated_time=#{sourceUpdatedTime},
    update_time=NOW()
WHERE provider_id=#{providerId}
  AND project_mapping_id=#{projectMappingId}
  AND provider_session_id=#{providerSessionId}
